```rust
#[derive(Subcommand)]
pub enum AgentCmd {
    /// Start Hiranyagarbha AI Native runtime
    Start,
    /// Stop the agent
    Stop,
    /// Restart the agent
    Restart,
    /// Agent health + session info
    Status,
    /// Interactive REPL chat with Hiranyagarbha
    Chat,
    /// Single question, print answer, exit
    Ask { question: String },
    /// Stream agent logs
    Logs,
    /// Agent config
    Config,
    /// Memory management
    Memory {
        #[command(subcommand)]
        cmd: MemoryCmd,
    },
    /// RAG knowledge base
    Rag {
        #[command(subcommand)]
        cmd: RagCmd,
    },
    /// Active / queued tasks
    Tasks,
    /// Warp agent integration status
    Warp,
    /// NCL integration status
    Ncl,
    /// Oasis bridge status
    Oasis,
}

#[derive(Subcommand)]
pub enum MemoryCmd {
    /// List memory entries
    Ls,
    /// Flush session memory
    Flush,
}

#[derive(Subcommand)]
pub enum RagCmd {
    /// Rebuild the RAG index
    Index,
    /// Direct RAG query (no LLM)
    Query { question: String },
