pub async fn run(cfg: &Config) -> Result<()> {
    let node_host = cfg.node.rpc_host.clone();
    let node_port = cfg.node.rpc_port;
    let agent_url = cfg.agent.url.clone();

    enable_raw_mode()?;
    let mut stdout = io::stdout();
