        .unwrap_or_else(|e| die(&format!("read from {addr}: {e}")));

    let resp: Value = serde_json::from_str(&resp_line)
        .unwrap_or_else(|e| die(&format!("invalid JSON response: {e}")));

    if let Some(err) = resp.get("error") {
        die(&format!("RPC error: {err}"));
    }
    resp["result"].clone()
