/// Build an undo block from a transaction set.
/// `utxo_lookup` resolves each input's previous UTXO info.
pub fn build_undo_block<F>(
    height: u64,
    block_hash: [u8; 32],
    transactions: &[crate::tx::Transaction],
    mut utxo_lookup: F,
) -> UndoBlock
where
    F: FnMut(&[u8; 32], u32) -> Option<RestoredUtxo>,
