    ValueNotConserved {
        tx_index: usize,
        inputs_sum: u64,
        outputs_plus_fee: u64,
    },
    /// Numeric overflow while summing UTXO inputs or outputs. Treated as
    /// a hard rejection to avoid masking malformed data with wrap-around
    /// arithmetic.
    ValueOverflow {
        tx_index: usize,
    },
