fn parse_backend(raw: &str) -> DcrBackend {
    match raw.trim().to_ascii_lowercase().as_str() {
        "cpu" => DcrBackend::Cpu,
        "gpu" => DcrBackend::Gpu,
        _ => DcrBackend::Auto,
    }
}

