            let available = large_min > 0;
            HugePagesInfo {
                available,
                allocated: false,
                page_size: if available { large_min } else { 4096 },
            }
        }
        #[cfg(not(target_os = "windows"))]
        {
            HugePagesInfo {
                available: false,
                allocated: false,
                page_size: 4096,
            }
        }
    }
