            ok_json(serde_json::json!({
                "status": "ok",
                "htlc": rec,
            })),
        ),
        Ok(None) => (
            StatusCode::NOT_FOUND,
            err_json(format!("HTLC not found: {hash_hex}")),
        ),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, err_json(e.to_string())),
    }
}

