        // Build Ankr URL
        let key = ankr.effective_api_key();
        match key {
            Some(k) => format!("https://rpc.ankr.com/{}/{}", self.chain_id, k),
            None => format!("https://rpc.ankr.com/{}", self.chain_id),
        }
    }
