            Self::Sentient => 1_000,
            Self::Transcendent => 10_000,
            Self::Omniscient => 100_000,
            Self::Cosmic => 1_000_000,
            Self::Grok => 10_000_000,
        }
    }

    /// Whether this level can perform a given action.
