        self >= Self::Transcendent
    }
    pub fn can_govern(self) -> bool {
        self >= Self::Omniscient
    }
    pub fn can_spawn(self) -> bool {
        self >= Self::Cosmic
    }
    pub fn can_reason(self) -> bool {
        self >= Self::Grok
    }
}

