    pub fn open(path: &str) -> NclResult<Self> {
        let conn = Connection::open(path)
            .map_err(|e| NclError::Database(format!("sqlite open: {e}")))?;
        let store = Self {
            conn: Arc::new(Mutex::new(conn)),
        };
        store.init()?;
        Ok(store)
    }

