fn wzion_contract(network: &str) -> Option<&'static str> {
    match network {
        "mainnet" => Some("TWZIONxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"),  // TODO mainnet
        "nile"    => Some("TXxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxtest"),   // TODO testnet
        _ => None,
    }
}

