        let success_rate = if initiated > 0 {
            completed as f64 / initiated as f64
        } else {
            0.0
        };

        MetricsSnapshot {
            transfers_initiated: initiated,
            transfers_completed: completed,
            transfers_failed: failed,
            transfers_pending: pending,
            success_rate,
        }
    }
}

