        rpc_url: &str,
        tx_b64: &str,
    ) -> WarpResult<String> {
        use serde::{Deserialize, Serialize};
        use serde_json::{json, Value};

        #[derive(Serialize)]
        struct Req<'a> {
            jsonrpc: &'a str,
            id: u32,
            method: &'a str,
            params: Value,
        }
        #[derive(Deserialize)]
        struct Resp {
            result: Option<Value>,
            error: Option<Value>,
        }

        let body = Req {
            jsonrpc: "2.0",
            id: 1,
            method: "sendTransaction",
            params: json!([tx_b64, {"encoding": "base64", "preflightCommitment": "confirmed"}]),
        };
        let resp: Resp = client
            .post(rpc_url)
            .json(&body)
            .send()
