    /// Calculate XP for a completed transfer.
    ///
    /// Returns `u64` so it can be passed directly to `ConsciousnessEngine::add_xp()`.
    pub fn for_transfer(ev: &WarpXpEvent) -> u64 {
        let base: u64 = 50;
