        let cross: u64 = if ev.is_cross_family() { 25 } else { 0 };
        base + volume + cross
    }

    /// Minimum possible XP (base only, tiny amount, same-family).
    pub const MIN_XP: u64 = 50;

    /// Maximum possible XP (base + volume cap + cross bonus).
    pub const MAX_XP: u64 = 275;
}

